-- a03: a pair and its two projections.

axiom Nat : Type 0

def p : (a : Nat) * Nat := (1, 2)
def firstOfP : Nat := p.1
def secondOfP : Nat := p.2
def swapped : (a : Nat) * Nat := (p.2, p.1)
def nestedPair : (a : Nat) * ((b : Nat) * Nat) := (1, (2, 3))

-- a06: the empty collection at both formers.  "()" is the section and
-- "absurd" is the elimination with no branch.
-- SB-D1 writes both types out, which Stage A postulated.

def Unit : Type 0 := prod ()
def Empty : Prop := sum ()

def u : Unit := ()
def uTuple : Unit := tuple ()
def fromEmpty : (0 A : Type 0) -> (x : Empty) -> A :=
  fun (0 A : Type 0) (x : Empty) => absurd x

-- b06: the universe of an arrow is imax, not max.  A codomain at
-- level zero puts the whole arrow at level zero however high the
-- domain sits, which is what keeps Prop closed under the arrow.

axiom A : Type 0
axiom B : Type 1

def impFromType : Prop := (0 x : A) -> sum ()
def impFromHigher : Prop := (0 x : B) -> sum ()
def impFromProp : Prop := (0 x : sum ()) -> sum ()

-- b09: the two collection type words of SB-D1.  "sum" is the left
-- former and "prod" is the right former at the collection shape over
-- the diagram of the items, and neither is a former of the kernel:
-- both are sugar rows of SPEC.md section 7.

axiom Nat : Type 0

def Two : Type 0 := sum (Nat, Nat)
def Pair : Type 0 := prod (Nat, Nat)
def Triple : Type 0 := prod (Nat, Nat, Nat)
def Void : Prop := sum ()
def Unit : Type 0 := prod ()

def leftOfTwo : Two := inj 0 of 2 1
def rightOfTwo : Two := inj 1 of 2 2
def onePair : Pair := tuple (1, 2)
def oneTriple : Triple := tuple (1, 2, 3)
def star : Unit := tuple ()

-- b10: case over a sum, with the motive and without it.  The branch
-- binder takes its type from the leg of the diagram, never from the
-- annotation the branch writes (SB-D32).

axiom Nat : Type 0

def Two : Type 0 := sum (Nat, Nat)

def plain : (x : Two) -> Nat :=
  fun (x : Two) => case x with | 0 (a : Nat) => a | 1 (b : Nat) => natAdd b 1

def withMotive : (x : Two) -> Nat :=
  fun (x : Two) => case x as y return Nat with | 0 (a : Nat) => a | 1 (b : Nat) => b

def fromVoid : (0 A : Type 0) -> (x : sum ()) -> A :=
  fun (0 A : Type 0) (x : sum ()) => absurd x

-- b11: the leg projection ".k" on a right former, zero based, and the
-- two pair projections ".1" and ".2" on a point shape.  The two rows
-- of the sugar table differ by the type of the scrutinee (SA-D16).

axiom Nat : Type 0

def Triple : Type 0 := prod (Nat, Nat, Nat)

def t : Triple := tuple (1, 2, 3)
def legZero : Nat := t.0
def legOne : Nat := t.1
def legTwo : Nat := t.2

def p : (a : Nat) * Nat := (4, 5)
def firstOfP : Nat := p.1
def secondOfP : Nat := p.2
def rebuilt : (a : Nat) * Nat := (p.1, p.2)

-- b12: the booleans of the prims.  "natEq" and "natLt" answer at the
-- two leg sum of the unit type, which SB-D1 now writes out, so the
-- answer of a prim is a term of a type the surface can spell.

def Bool : Type 0 := sum ((prod () : Type 0), (prod () : Type 0))

def yes : Bool := natEq 4 4
def no : Bool := natEq 4 5
def below : Bool := natLt 1 2
def true : Bool := inj 0 of 2 ()
def false : Bool := inj 1 of 2 ()

def toNat : (b : Bool) -> Nat -> Nat :=
  fun (b : Bool) (n : Nat) => case b with | 0 (x : prod ()) => n | 1 (y : prod ()) => natAdd n 1

-- c04: the tags of a sum with a payload free leg and a payload leg.
-- The unit leg has no runtime field, so its tag carries no payload and
-- its branch has arity zero.

def Opt : Type 0 := sum ((prod () : Type 0), Nat)

def none : Opt := inj 0 of 2 (tuple ())
def some : Opt := inj 1 of 2 7

def unwrap : (x : Opt) -> Nat :=
  fun (x : Opt) => case x with | 0 (u : prod ()) => 0 | 1 (v : Nat) => v

-- Dependent branches instantiate the motive at their own constructors.
def Two : Type 0 := sum (Nat, Nat)
def F : (x : Two) -> Type 0 := fun (x : Two) => case x as z return Type 0 with | 0 (a : Nat) => Nat | 1 (b : Nat) => prod (Nat, Nat)
def choose : (x : Two) -> F x := fun (x : Two) => case x as y return F y with | 0 (a : Nat) => a | 1 (b : Nat) => tuple (b, b)

def G : (x : Two) -> Type 0 := fun (x : Two) => case x as z return Type 0 with | 0 (a : Nat) => Nat | 1 (b : Nat) => (n : Nat) -> Nat
def chooseFun : (x : Two) -> G x := fun (x : Two) => case x as y return G y with | 0 (a : Nat) => a | 1 (b : Nat) => fun (n : Nat) => natAdd b n

-- A runtime let definition resolves a later dependent tuple type.
def Two : Type 0 := sum (Nat, Nat)
def F : (x : Two) -> Type 0 := fun (x : Two) => case x as z return Type 0 with | 0 (a : Nat) => Nat | 1 (b : Nat) => prod (Nat, Nat)
def n : Nat := let tag : Two := inj 1 of 2 5 in let v : F tag := tuple (5, 6) in v.0

-- Complete function-valued bodies under existing runtime binders.
def later : (f : Nat -> Nat -> Nat) -> (x : Nat) -> Nat -> Nat :=
  fun (f : Nat -> Nat -> Nat) (x : Nat) => f x

def letHead : (x : Nat) -> Nat -> Nat :=
  fun (x : Nat) => let z : Nat := x in natAdd z

def lifted : (x : Nat) -> prod (Nat -> Nat -> Nat) :=
  fun (x : Nat) => tuple (fun (y : Nat) => natAdd (natAdd x y))

def Two : Type 0 := sum (Nat, Nat)
def caseHead : (bias : Nat) -> (s : Two) -> Nat -> Nat :=
  fun (bias : Nat) (s : Two) =>
    case s with
    | 0 (a : Nat) => natAdd (natAdd bias a)
    | 1 (b : Nat) => fun (n : Nat) => natAdd b n

-- d01: the literals and all five prims.  natEq and natLt answer at the
-- two leg sum of SB-D1, and one case reads that answer back into a Nat,
-- so every prim of M0 reaches the emitter from one file.
-- main is 17.

def Bool : Type 0 := sum ((prod () : Type 0), (prod () : Type 0))

def toNat : (b : Bool) -> Nat :=
  fun (b : Bool) => case b with | 0 (x : prod ()) => 0 | 1 (y : prod ()) => 1

def scaled : Nat := natMul (natAdd 2 3) (natSub 7 4)
def flags : Nat := natAdd (toNat (natEq 4 4)) (toNat (natLt 1 2))

def main : Nat := natAdd scaled flags

-- d03: a pair built and projected twice, once from a definition and
-- once from the answer of a function.
-- main is 26.

def p : (a : Nat) * Nat := (11, 6)

def mk : (x : Nat) -> (a : Nat) * Nat :=
  fun (x : Nat) => (x, natAdd x 1)

def q : (a : Nat) * Nat := mk 4

def main : Nat := natAdd (natAdd p.1 p.2) (natAdd q.1 q.2)

-- d04: a three leg tuple built and projected.  One struct holds the
-- three legs, so a pair of pairs is a different golden (SD-M3).
-- main is 10.

def Triple : Type 0 := prod (Nat, Nat, Nat)

def t : Triple := tuple (2, 3, 4)

def main : Nat := natAdd (natMul t.0 t.1) t.2

-- d06: a lambda that captures a local, stored in a pair and applied
-- later.  One capture is a parameter and the other is a let bound
-- local, so both capture paths of SD-D2 run.
-- main is 31.

def mk : (x : Nat) -> (f : Nat -> Nat) * Nat :=
  fun (x : Nat) => ((fun (y : Nat) => natAdd x y), natMul x 2)

def mkLet : (x : Nat) -> (f : Nat -> Nat) * Nat :=
  fun (x : Nat) => let z : Nat := natAdd x 1 in ((fun (y : Nat) => natAdd z y), z)

def main : Nat :=
  natAdd (natAdd ((mk 5).1 6) (mk 5).2) (natAdd ((mkLet 2).1 4) (mkLet 2).2)

-- A case retains its sum tid after polymorphic identity returns any.
-- main is 1.
def Bool : Type 0 := sum ((prod () : Type 0), (prod () : Type 0))
def id : (0 A : Type 0) -> (x : A) -> A :=
  fun (0 A : Type 0) (x : A) => x
def main : Nat :=
  case (id Bool (natEq 1 1)) with
  | 0 (x : prod ()) => 0
  | 1 (y : prod ()) => 1

mu N : Type 0 with
| zero : N
| succ : N -> N

def rec dbl : N -> N := fun (n : N) => case n as x in N return N with | zero => zero | succ m => succ (succ (dbl m))

def n0 : N := succ zero
def n1 : N := succ (dbl n0)
def n2 : N := succ (dbl n1)
def n3 : N := succ (dbl n2)
def n4 : N := succ (dbl n3)
def n5 : N := succ (dbl n4)
def n6 : N := succ (dbl n5)
def n7 : N := succ (dbl n6)
def n8 : N := succ (dbl n7)
def n9 : N := succ (dbl n8)
def n10 : N := succ (dbl n9)
def n11 : N := succ (dbl n10)

def rec toNat : N -> Nat := fun (n : N) => case n as x in N return Nat with | zero => 0 | succ m => natAdd 1 (toNat m)

def main : Nat := natAdd 0 (toNat n11)

-- A big Nat survives a closure environment and a polymorphic aggregate.
def box : (0 A : Type 0) -> (x : A) -> (a : A) * A :=
  fun (0 A : Type 0) (x : A) => (x, x)
def mk : (x : Nat) -> Nat -> Nat :=
  fun (x : Nat) => fun (y : Nat) => natSub (natAdd x y) x
def main : Nat :=
  (mk ((box Nat 12345678901234567890123456789).1)) 19

def Unit : Type 0 := (prod () : Type 0)
def Both : Type 0 := sum (Unit, Unit)
def choose : (1 x : Nat) -> (tag : Both) -> Nat :=
  fun (1 x : Nat) (tag : Both) => case tag with | 0 (z : Unit) => x | 1 (z : Unit) => x
def nested : (1 x : Nat) -> (tag : Both) -> Nat :=
  fun (1 x : Nat) (tag : Both) => case tag with
  | 0 (z : Unit) => (case tag with | 0 (w : Unit) => x | 1 (w : Unit) => x)
  | 1 (z : Unit) => x
def payload : (value : sum (Nat, Nat)) -> Nat :=
  fun (value : sum (Nat, Nat)) => case value with | 0 (1 x : Nat) => x | 1 (1 x : Nat) => x
def main : Nat := choose 7 (inj 0 of 2 (tuple ()))

mu Box : Type 0 with
| box : (1 field : Nat) -> Box
def pack : (1 x : Nat) -> Box := fun (1 x : Nat) => box x
def unpack : (1 b : Box) -> Nat := fun (1 b : Box) => case b as self in Box return Nat with | box 1 x => x
def pair : (1 x : Nat) -> (1 field : Nat) * Nat := fun (1 x : Nat) => (x, 0)
def main : Nat := unpack (pack 7)
